android.extraProguardRules:
# CRITICAL - Java serialization finds writeObject/readObject by NAME via
# reflection. R8 renaming them makes it fall back to DEFAULT serialization,
# which then hits expo-notifications' raw org.json.JSONObject field and throws
# java.io.NotSerializableException: org.json.JSONObject. That is exactly the
# error every scheduled reminder died with on release builds.
#
# Verified at source: NotificationContent.java declares
#   private JSONObject mBody;                       (JSONObject is NOT Serializable)
#   private void writeObject(ObjectOutputStream)    (writes mBody.toString())
#   private void readObject(ObjectInputStream)
# expo-notifications ships its own proguard-rules.pro with this keep, but its
# build.gradle has NO consumerProguardFiles line, so that file is never applied
# to the app. The rules below are the only thing protecting it.
-keepclassmembers class * implements java.io.Serializable {
    static final long serialVersionUID;
    private static final java.io.ObjectStreamField[] serialPersistentFields;
    private void writeObject(java.io.ObjectOutputStream);
    private void readObject(java.io.ObjectInputStream);
    java.lang.Object writeReplace();
    java.lang.Object readResolve();
}
-keep class org.json.** { *; }

# JNI - native C++ resolves these by name, so renaming breaks the binding.
# react-native-nitro-modules (pulled in by react-native-iap) ships no proguard
# rules of its own and marks its bridge classes @DoNotStrip.
-keepclasseswithmembernames class * { native <methods>; }
-keep @com.facebook.proguard.annotations.DoNotStrip class * { *; }
-keepclassmembers class * { @com.facebook.proguard.annotations.DoNotStrip *; }
-keep class com.margelo.nitro.** { *; }

# React Native bridge - @ReactMethod methods are invoked from JS BY NAME, and
# ViewManagers are resolved by their registered name, so both need their members
# kept even though PackageList.java makes the classes themselves reachable.
-keep,includedescriptorclasses class * extends com.facebook.react.bridge.NativeModule { *; }
-keepclassmembers class * { @com.facebook.react.bridge.ReactMethod <methods>; }
-keep class * extends com.facebook.react.ReactPackage { *; }
-keep class * extends com.facebook.react.uimanager.ViewManager { *; }

# These four ship no consumerProguardFiles of their own and rely on the bridge
# above; keeping them outright costs a few KB and removes the guesswork.
-keep class com.reactnativecommunity.asyncstorage.** { *; }
-keep class com.reactnativegooglesignin.** { *; }
-keep class com.th3rdwave.safeareacontext.** { *; }
-keep class fr.greweb.reactnativeviewshot.** { *; }

# Sentry - without SourceFile/LineNumberTable every crash report we receive is
# an unreadable stack of a.b.c(). renamesourcefileattribute still hides the
# original file names, so this costs nothing but keeps reports usable.
-keepattributes SourceFile,LineNumberTable
-renamesourcefileattribute SourceFile
-keep class io.sentry.** { *; }
-dontwarn io.sentry.**

# Kotlin reflection - the expo-modules DSL reads annotations and generic
# signatures at runtime to build its module definitions.
-keepattributes *Annotation*,Signature,InnerClasses,EnclosingMethod,Exceptions

-keep class com.facebook.react.** { *; }
-keep class com.facebook.hermes.** { *; }
-keep class com.swmansion.** { *; }
-keep class expo.modules.** { *; }
-keep class host.exp.** { *; }
-keep class expo.modules.notifications.** { *; }
-keep class androidx.health.connect.** { *; }
-keep class com.razorpay.** { *; }
-keep class com.google.firebase.** { *; }
-keep class com.google.android.gms.** { *; }
-dontwarn org.slf4j.**
-keep class com.facebook.jni.** { *; }

# Samsung Health Data SDK - the AAR is a FLAT FILE dependency
# (implementation files("libs/...aar")), and Gradle does not apply an AAR's
# bundled consumer ProGuard rules when it is consumed that way. The SDK ships
# its own proguard.txt keeping every public member of these packages; because
# nothing applies it for us, the rules below are the only thing standing
# between R8 and a stripped/renamed SDK in release builds. The SDK resolves
# data types and fields by name across an AIDL service boundary to Samsung
# Health, so renaming them fails at run time, not at build time.
-keep public class com.samsung.android.sdk.health.data.** { public protected *; }
-keep public class com.samsung.android.sdk.health.data.data.entries.** { <fields>; public protected *; }
-keep public class com.samsung.android.sdk.health.data.request.** { <fields>; public protected *; }
-keep @interface com.samsung.android.sdk.health.data.internal.annotation.ApiVersion
-keepclassmembers class * {
    @com.samsung.android.sdk.health.data.internal.annotation.ApiVersion <methods>;
}
-dontwarn com.samsung.android.sdk.health.data.**
